/* ── 판매수량 → 소셜 프루프 문구 ── */
function getSocialProof(sale) {
  if (sale >= 800) return { label: "오늘 인기 급상승 중", hot: true };
  if (sale >= 400) return { label: `${Math.round(sale/60)}명이 오늘 찾은 상품`, hot: true };
  if (sale >= 200) return { label: `이번 달 ${Math.round(sale/6)}명 구매`, hot: false };
  if (sale >= 100) return { label: `재구매 고객이 많은 상품`, hot: false };
  if (sale >= 50)  return { label: `꾸준히 찾는 상품`, hot: false };
  return { label: `신규 입고 상품`, hot: false };
}

